const ON = new Set(["1", "true", "on", "yes"]);

export type EnvFlagState = EnvFlag & { state: "on" | "off" | "set" | "unset" | "value"; value: string | null };

/** What the page may show for one env flag. A secret NEVER shows a value; a mode shows a short safe value only. */
export function envFlagState(f: EnvFlag, env: Record<string, string | undefined>): EnvFlagState {
  const raw = env[f.key];
  if (f.kind === "secret") return { ...f, state: raw ? "set" : "unset", value: null };
  if (f.kind === "mode") {
    const v = raw?.trim() ?? "";
    if (!v) return { ...f, state: "unset", value: null };
    return { ...f, state: "value", value: /^[a-z0-9._:-]{1,24}$/i.test(v) ? v : "(set)" };
  }
  return { ...f, state: raw && ON.has(raw.trim().toLowerCase()) ? "on" : "off", value: null };
}

// ---------------------------------------------------------------------------
// Launch pair
// ---------------------------------------------------------------------------

export const LAUNCH_PAIR = ["cyrus_studio_public_enabled", "cyrus_tok_live"] as const;
export const LAUNCH_CONFIRM_ON = "LAUNCH CYRUS";
export const LAUNCH_CONFIRM_OFF = "CLOSE CYRUS";
const isOn = (v: string | undefined) => v === "true";

export function launchPairState(stored: Record<string, string>) {
  const studioPublic = isOn(stored.cyrus_studio_public_enabled), tokensLive = isOn(stored.cyrus_tok_live);
  return { studioPublic, tokensLive, consistent: studioPublic === tokensLive, on: studioPublic && tokensLive };
}

/** Decide a pair flip: both keys get the same value; the typed confirmation must match the direction. */
export function launchPairFlip(on: boolean, typed: string): { ok: true; writes: { key: string; value: string | null }[] } | { ok: false; error: string } {
  const want = on ? LAUNCH_CONFIRM_ON : LAUNCH_CONFIRM_OFF;
  if (typed.trim() !== want) return { ok: false, error: `Type ${want} to confirm.` };
  return { ok: true, writes: LAUNCH_PAIR.map((key) => ({ key, value: on ? "true" : null })) };
}

// ---------------------------------------------------------------------------
// Kill switches
// ---------------------------------------------------------------------------

export type KillSwitch = { id: "builds" | "gateway" | "networking"; key: string; label: string; what: string; killedWhen: "true" | "unset" };
export const KILL_SWITCHES: KillSwitch[] = [
  { id: "builds", key: "cyrus_builds_paused", label: "Global build pause", what: "No new build, change or import starts. Running builds finish; mods, installs and downloads keep working.", killedWhen: "true" },
  { id: "gateway", key: "cyrus_ai_gw_kill", label: "AI gateway kill", what: "Every mod's Nxeon AI call answers 503 before any other check.", killedWhen: "true" },
  { id: "networking", key: "cyrus_mod_networking_enabled", label: "Mod networking", what: "Off blocks all mod networking (the vetted wrapper refuses every host).", killedWhen: "unset" },
];

export function killState(k: KillSwitch, stored: Record<string, string>): "killed" | "running" {
  return k.killedWhen === "true" ? (stored[k.key] === "true" ? "killed" : "running") : (stored[k.key] === "true" ? "running" : "killed");
}

/** The write for "kill" or "resume". Resuming needs the confirm box; killing never does (the safe direction). */
export function killWrite(k: KillSwitch, kill: boolean, confirmed: boolean): { ok: true; key: string; value: string | null } | { ok: false; error: string } {
  if (!kill && !confirmed) return { ok: false, error: `Tick the box to confirm turning ${k.label.toLowerCase()} back on.` };
  if (k.killedWhen === "true") return { ok: true, key: k.key, value: kill ? "true" : null };
  return { ok: true, key: k.key, value: kill ? null : "true" };
}

