// Cyrus admin: per-game readiness checklists, parsed from the game agents' READINESS.md files.
// parseReadiness is PURE (unit-tested); loadReadiness reads files (server only).
//
// Where the files come from, first hit wins:
//   1. docs/cyrus/readiness/<gameId>.md in the repo (what production reads; refreshed at merge time)
//   2. $CYRUS_READINESS_DIR/game-<gameId>/READINESS.md (dev/agents: the live notes folder)
// A game without a file shows "no readiness checklist yet" (honest empty state).
import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";

export type ReadinessItem = { text: string; done: boolean; kind: "task" | "decision" };
export type ReadinessSection = { heading: string; items: ReadinessItem[] };
export type Readiness = { title: string; sections: ReadinessSection[]; open: number; done: number; decisions: number; source: string };

const TASKY = /(left|before|must|should|nice|checklist|todo|maintenance|needed|decision|done|built|status)/i;
const clean = (s: string) => s.replace(/\*\*/g, "").replace(/\s+/g, " ").trim().slice(0, 240);

export function parseReadiness(md: string, source = ""): Readiness {
  const lines = md.replace(/\r/g, "").split("\n");
  let title = "";
  const sections: ReadinessSection[] = [];
  let cur: ReadinessSection | null = null;
  let headingDone = false;
  let decision = false;
  let curLevel = 0;
  for (const line of lines) {
    const h = /^(#{1,4})\s+(.*)$/.exec(line);
    if (h) {
      const text = clean(h[2]);
      if (h[1] === "#" && !title) { title = text; continue; }
      const level = h[1].length;
      if (TASKY.test(text)) {
        cur = { heading: text, items: [] };
        sections.push(cur);
        curLevel = level;
        headingDone = /\b(done|built)\b/i.test(text) && !/left|before/i.test(text);
        decision = /decision/i.test(text);
      } else if (cur && level > curLevel) {
        // A plain sub-heading inside a checklist section keeps the parent's meaning.
        cur = { heading: `${sections[sections.length - 1].heading.split(" › ")[0]} › ${text}`, items: [] };
        sections.push(cur);
      } else cur = null;
      continue;
    }
    if (!cur) continue;
    const cb = /^\s*[-*]\s+\[( |x|X)\]\s+(.*)$/.exec(line);
    if (cb) { cur.items.push({ text: clean(cb[2]), done: cb[1] !== " ", kind: decision ? "decision" : "task" }); continue; }
    const num = /^(\d{1,2})\.\s+(.*)$/.exec(line);
    if (num) {
      const t = clean(num[2]);
      // "Decided: ..." in a decisions list is done; everything else in a decisions list is open.
      const done = headingDone || (decision && /^decided\b/i.test(t));
      cur.items.push({ text: t, done, kind: decision ? "decision" : "task" });
    }
  }
  const kept = sections.filter((s) => s.items.length).map((s) => ({ ...s, items: s.items.slice(0, 40) }));
  const all = kept.flatMap((s) => s.items);
  return {
    title,
    sections: kept,
    open: all.filter((i) => !i.done && i.kind === "task").length,
    done: all.filter((i) => i.done).length,
    decisions: all.filter((i) => !i.done && i.kind === "decision").length,
    source,
  };
}

export async function loadReadiness(gameId: string): Promise<Readiness | null> {
  if (!/^[a-z0-9]{2,20}$/.test(gameId)) return null;
  const candidates = [join(process.cwd(), "docs", "cyrus", "readiness", `${gameId}.md`)];
  if (process.env.CYRUS_READINESS_DIR) candidates.push(join(process.env.CYRUS_READINESS_DIR, `game-${gameId}`, "READINESS.md"));
  for (const p of candidates) {
    try {
      const md = await readFile(p, "utf8");
      return parseReadiness(md.slice(0, 200_000), p.includes(`${join("docs", "cyrus", "readiness")}`) ? `docs/cyrus/readiness/${gameId}.md` : p);
    } catch { /* next */ }
  }
  return null;
}

/** Game ids that have a readiness file in the repo (some games are not in the registry yet). */
export async function listReadinessIds(): Promise<string[]> {
  try {
    return (await readdir(join(process.cwd(), "docs", "cyrus", "readiness"))).filter((f) => /^[a-z0-9]{2,20}\.md$/.test(f)).map((f) => f.slice(0, -3)).sort();
  } catch {
    return [];
  }
}
