// Version-support registry: the one place that says what each Minecraft version needs (JDK, pack formats,
// capabilities) and whether Cyrus may build for it. Replaces scattered version lists and the old packFormatFor.
// Data lives in registry.json so the Next.js app and the plain-Node build service can read the same file.
import registryData from "./registry.json";

export type Capability = "itemModelDefinitions" | "dialogApi" | "adventure5" | "dataComponentsStable" | "animatedCreatures" | "legacyCustomModelData";
export type FormatVersion = { major: number; minor: number };
export type VersionRow = {
  id: string;
  family: "1.21" | "26";
  javaRelease: 21 | 25;
  status: "supported" | "preview" | "legacy" | "blocked";
  buildable: boolean;
  paperCoordinate: string | null;
  /** Exact stable Paper SERVER build and its jar sha256 (what Test Flight boots); independent of paperCoordinate
   *  (the compile API). null/absent = no pin, so the version cannot be test-flown. */
  paperBuild?: number | null;
  paperServerSha256?: string | null;
  resourcePack: FormatVersion | null;
  dataPack: FormatVersion | null;
  resourcePackClientVerified: boolean;
  capabilities: Capability[];
};

export const VERSIONS: readonly VersionRow[] = registryData.versions as VersionRow[];

/** Exact match only: a version the registry does not list is unknown, never guessed. */
export function getVersion(id: string): VersionRow | null {
  return VERSIONS.find((v) => v.id === id) ?? null;
}

export const buildableVersions = (): VersionRow[] => VERSIONS.filter((v) => v.buildable);
export const hasCapability = (id: string, c: Capability): boolean => !!getVersion(id)?.capabilities.includes(c);

export type PackFormatResult =
  | { ok: true; format: FormatVersion; clientVerified: boolean }
  | { ok: false; error: string };

/** Resource-pack format for a version. Fails closed: unknown version, unknown number, or no item-model support. */
export function resourcePackFormat(mc: string, opts: { needsItemModels?: boolean } = {}): PackFormatResult {
  const v = getVersion(mc);
  if (!v) return { ok: false, error: `Minecraft ${mc} is not in the version registry` };
  if (!v.resourcePack) return { ok: false, error: `resource pack format for ${mc} is not verified yet` };
  if (opts.needsItemModels && !v.capabilities.includes("itemModelDefinitions")) {
    return { ok: false, error: v.capabilities.includes("legacyCustomModelData")
      ? `${mc} has no item model definitions (needs 1.21.4+); on ${mc} custom textures use the legacy custom-model-data path (carrier item + setCustomModelData)`
      : `${mc} has no item model definitions (needs 1.21.4+)` };
  }
  return { ok: true, format: v.resourcePack, clientVerified: v.resourcePackClientVerified };
